#!/usr/bin/env python
# -*- coding: utf-8 -*-

"""
Script for merging distributed detection results
"""
import os
import json
import argparse
from collections import defaultdict
from pathlib import Path


def merge_results(output_dir: str, world_size: int):
    """Merging result files generated by multiple ranks"""
    
    print(f"Start merging results from {world_size} ranks")
    
    file_types = [
        "known_bucket", "unknown_bucket", "ambiguous_bucket",
        "known_bucket_details", "unknown_bucket_details", "ambiguous_bucket_details"
    ]
    
    for file_type in file_types:
        merged_lines = []
        
        for rank in range(world_size):
            rank_file = os.path.join(output_dir, f"{file_type}_rank{rank}.jsonl")
            
            if os.path.exists(rank_file):
                with open(rank_file, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
                    merged_lines.extend(lines)
                    print(f"Reading {rank_file}: {len(lines)} lines")
            else:
                print(f"Warning: File does not exist {rank_file}")
        
        merged_file = os.path.join(output_dir, f"{file_type}_merged.jsonl")
        with open(merged_file, 'w', encoding='utf-8') as f:
            f.writelines(merged_lines)

        print(f"Successfully merged into {merged_file}: Total {len(merged_lines)} lines")

    stats = {
        "known": 0,
        "unknown": 0,
        "ambiguous": 0
    }
    
    for category in ["known", "unknown", "ambiguous"]:
        merged_file = os.path.join(output_dir, f"{category}_bucket_merged.jsonl")
        if os.path.exists(merged_file):
            with open(merged_file, 'r') as f:
                stats[category] = len(f.readlines())
    
    report_file = os.path.join(output_dir, "summary_report.txt")
    with open(report_file, 'w') as f:
        f.write(f"Total number of samples: {sum(stats.values())}\n")
        f.write(f"Known: {stats['known']} ({stats['known']/sum(stats.values())*100:.2f}%)\n")
        f.write(f"Unknown: {stats['unknown']} ({stats['unknown']/sum(stats.values())*100:.2f}%)\n")
        f.write(f"Ambiguous: {stats['ambiguous']} ({stats['ambiguous']/sum(stats.values())*100:.2f}%)\n")
        f.write("=" * 50 + "\n")

    print("\nSummary Report:")
    with open(report_file, 'r') as f:
        print(f.read())
    
    clean_rank_files = input("\nDo you want to delete the original rank files?(y/n): ").strip().lower() == 'y'
    if clean_rank_files:
        for file_type in file_types:
            for rank in range(world_size):
                rank_file = os.path.join(output_dir, f"{file_type}_rank{rank}.jsonl")
                if os.path.exists(rank_file):
                    os.remove(rank_file)
                    print(f"already deleted: {rank_file}")


def main():
    parser = argparse.ArgumentParser(description="Merging distributed detection results")
    parser.add_argument("--output_dir", type=str, required=True)
    parser.add_argument("--world_size", type=int, required=True, help="Number of distributed processes used during detection")
    
    args = parser.parse_args()
    merge_results(args.output_dir, args.world_size)


if __name__ == "__main__":
    main()